import{_ as o,b as a,c as e,I as n}from"./chunks/framework.C6cPs9Ia.js";const d=JSON.parse('{"title":"通学路 23 分钟 BGM 清单·二次元特辑","description":"高中生的通学路歌单分享——23 分钟的二次元 BGM 精选与每首歌的小故事","frontmatter":{"title":"通学路 23 分钟 BGM 清单·二次元特辑","date":"2026-07-22T00:00:00.000Z","tags":["音乐","歌单","日常"],"cover":"/LQY/images/cover-c.jpg","head":[["meta",{"name":"description","content":"高中生的通学路歌单分享——23 分钟的二次元 BGM 精选与每首歌的小故事"}],["meta",{"name":"keywords","content":"歌单, 通学路, 二次元音乐, 日常"}]]},"headers":[],"relativePath":"posts/commute-playlist.md","filePath":"posts/commute-playlist.md"}'),r={name:"posts/commute-playlist.md"};function s(i,t,p,l,m,c){return a(),e("div",null,[...t[0]||(t[0]=[n('<p>家和学校之间隔 23 分钟公交。这个长度的路程有个讲究：<strong>不长不短，正好一张 EP。</strong></p><p>所以我的歌单是按&quot;23 分钟一循环&quot;设计的。以下是目前在循环的版本，欢迎评论区抄作业/交流。</p><hr><h2 id="第一乐章-出发-4-min" tabindex="-1">第一乐章：出发（4 min） <a class="header-anchor" href="#第一乐章-出发-4-min" aria-label="Permalink to &quot;第一乐章：出发（4 min）&quot;">​</a></h2><p><strong>1. 《踢出个未来》节奏感的开场</strong>——上车坐下戴耳机的固定仪式感。前奏一响，世界切频道。</p><p><strong>2. 某燃系番 OP</strong>——早八人的 adrenaline。副歌那声&quot;上吧&quot;我怀疑是唱给我背英语单词的。</p><h2 id="第二乐章-通勤中段-10-min" tabindex="-1">第二乐章：通勤中段（10 min） <a class="header-anchor" href="#第二乐章-通勤中段-10-min" aria-label="Permalink to &quot;第二乐章：通勤中段（10 min）&quot;">​</a></h2><p><strong>3. Lo-fi × 动画 BGM 混剪歌单</strong>——窗外城市还没完全醒，适合放这种半梦半醒的曲子。</p><p><strong>4. 《群青》</strong>——看到&quot;蓝色&quot;就想起本命的发色，这题超纲了，不解释，反正在我歌单里它就是特别的存在。</p><p><strong>5. 某治愈番 ED</strong>——慢下来的一站。公交过桥的时候看江面，这首歌配这个画面，白给的世界名画。</p><h2 id="第三乐章-到站前-9-min" tabindex="-1">第三乐章：到站前（9 min） <a class="header-anchor" href="#第三乐章-到站前-9-min" aria-label="Permalink to &quot;第三乐章：到站前（9 min）&quot;">​</a></h2><p><strong>6. 8-bit Chiptune 混音歌单</strong>——像素时代的旋律现代混音，一路听回网页游戏的黄金年代。快到站的那首鼓点密集得正好当&quot;起立铃&quot;。</p><p><strong>7. 本命应援曲循环</strong>——下车前最后一首固定留给它。像给这一天上了个蓝色的 buff。</p><div class="tip custom-block"><p class="custom-block-title">歌单管理守则</p><ul><li>通学歌单一周换一版，跟不上季节和心情的歌会进&quot;冷宫&quot;</li><li>音量永远 60%——要听得见报站，错过站的下场很惨（亲身经历，那次走到了邻校门口）</li><li>单曲循环会上瘾，但一天最多循环三次，防止&quot;这首歌从此变成做题曲&quot;的悲剧</li></ul></div><h2 id="一个小发现" tabindex="-1">一个小发现 <a class="header-anchor" href="#一个小发现" aria-label="Permalink to &quot;一个小发现&quot;">​</a></h2><p>长期听下来发现一个规律：<strong>早上去听燃曲，晚自习后听治愈曲</strong>，是效率最高的组合。反过来试过一次，早上emo晚上亢奋，写作业写到凌晨一点，第二天语文课当场去世。</p><p>BGM 是生活的调色盘，但调色之前，先看清楚今天是什么底色。</p><hr><p>你们通学路上都在听什么？评论区交换一首，我来者不拒（只要不是《学猫叫》，虽然本窝确实是猫窝）。</p><p><em>——完。本歌单由一只睡过站两次的高中生倾情整理。</em></p>',20)])])}const h=o(r,[["render",s]]);export{d as __pageData,h as default};
